103	pub const DerivedConfig = struct {
104	    scrollback_compression: bool,
105	
106	    pub fn init(config: *const configpkg.Config) DerivedConfig {
107	        return .{
108	            .scrollback_compression = config.@"scrollback-compression",
109	        };
110	    }
