   101	    // setting `wantsLayer` to `true`.
   102	    //
   103	    // On iOS, views are always layer-backed, and `layer`
   104	    // is readonly, so instead we add it as a sublayer.
   105	    switch (comptime builtin.target.os.tag) {
   106	        .macos => {
