1252	            // The gates below mirror Kitty's image_is_animatable.
1253	
1254	            // No animation state was ever attached (plain image).
1255	            const anim = img.animation orelse continue;
1256	
1257	            // Stopped is the initial state of every animation: frames
1258	            // then only change client-driven (a=a c=N), never by time.
1259	            if (anim.state == .stopped) continue;
1260	
1261	            // Only the root frame exists; there is nothing to advance
1262	            // to yet even in the running state.
1263	            if (anim.frames.items.len == 0) continue;
1264	
1265	            // Unplaced images don't animate. This is our simpler
1266	            // approximation of Kitty's "is actually drawn" visibility
1267	            // gate; it is what stops an image that was transmitted but
1268	            // never placed from waking the renderer forever.
1269	            if (img.metadata.placement_count == 0) continue;
1270	
1271	            // The base pixel data hasn't arrived yet (e.g. an image
1272	            // restored from a snapshot); nothing can be displayed.
1273	            if (img.data.isPending()) continue;
1274	
1275	            // For the same reason, playback waits until every frame's
1276	            // pixels have arrived.
1277	            if (anim.hasPendingFrames()) continue;
1278	
1279	            // A zero total duration means every frame is gapless and
1280	            // no frame can ever be displayed, so the animation can
1281	            // never advance. This also guards the gapless-skip loop
1282	            // below from never terminating.
1283	            if (anim.durationMs() == 0) continue;
1284	
1285	            // A finite loop budget (a=a v=N) that ran out on an
1286	            // earlier tick froze playback on the last frame for good.
1287	            if (anim.max_loops > 0 and anim.current_loop >= anim.max_loops) continue;
