1289	            const shown_at: u64 = shown_at: {
1290	                // First tick since playback started (or since the
1291	                // current frame changed through another path, e.g.
1292	                // a=a c=N): the frame is considered shown as of now,
1293	                // and its gap starts counting from here.
1294	                const at = anim.frame_shown_at_ms orelse break :shown_at now_ms;
