 379	    /// Returns the index of the first placement drawn above `layer`, or
 380	    /// the number of placements if there is none. `placements` must be
 381	    /// sorted by layer.
 382	    fn layerEnd(
 383	        placements: []const Placement,
 384	        layer: terminal.RenderState.ImageLayer,
 385	    ) u32 {
 386	        for (placements, 0..) |p, i| {
 387	            if (@backingInt(p.layer) > @backingInt(layer)) return @intCast(i);
 388	        }
 389	        return @intCast(placements.len);
 390	    }
