  37	
  38	/// A cell is a single glyph within a terminal that should be rendered
  39	/// for a shaping call. Not all terminal cells may be present; only
   1	//! This structure caches the shaped cells for a given text run.
   2	//!
   3	//! At one point, shaping was the most expensive part of rendering text
   4	//! (accounting for 96% of frame time on my machine). To speed it up, this
   5	//! was introduced so that shaping results can be cached depending on the
   6	//! run.
   7	//!
   8	//! The cache key is the text run. The text run builds its own hash value
   9	//! based on the font, style, codepoint, etc. This just utilizes the hash that
  10	//! the text run provides.
  11	pub const Cache = @This();
  12	
  13	const std = @import("std");
  14	const Allocator = std.mem.Allocator;
  15	const font = @import("../main.zig");
  16	const CacheTable = @import("../../datastruct/main.zig").CacheTable;
  17	
  18	const log = std.log.scoped(.font_shaper_cache);
  19	
  20	/// Context for cache table.
  21	const CellCacheTableContext = struct {
  22	    pub fn hash(self: *const CellCacheTableContext, key: u64) u64 {
  23	        _ = self;
  24	        return key;
  25	    }
  26	    pub fn eql(self: *const CellCacheTableContext, a: u64, b: u64) bool {
  27	        _ = self;
  28	        return a == b;
  29	    }
  30	};
  31	
  32	/// Cache table for run hash -> shaped cells.
  33	const CellCacheTable = CacheTable(
  34	    u64,
  35	    []font.shape.Cell,
  36	    CellCacheTableContext,
  37	
  38	    // Capacity is slightly arbitrary. These numbers are guesses.
  39	    //
  40	    // I'd expect then an average of 256 frequently cached runs is a
  41	    // safe guess most terminal screens.
  42	    256,
  43	    // 8 items per bucket to give decent resiliency to important runs.
  44	    8,
  45	);
  46	
  47	/// The cache table of shaped cells.
  48	map: CellCacheTable,
  49	
  50	pub fn init() Cache {
  51	    return .{ .map = .{ .context = .{} } };
  52	}
  53	
  54	pub fn deinit(self: *Cache, alloc: Allocator) void {
  55	    self.clear(alloc);
  56	}
  57	
  58	/// Get the shaped cells for the given text run,
  59	/// or null if they are not in the cache.
  60	pub fn get(self: *Cache, run: font.shape.TextRun) ?[]const font.shape.Cell {
  61	    return self.map.get(run.hash);
  62	}
  63	
  64	/// Insert the shaped cells for the given text run into the cache.
  65	///
  66	/// The cells will be duplicated.
  67	pub fn put(
  68	    self: *Cache,
  69	    alloc: Allocator,
  70	    run: font.shape.TextRun,
  71	    cells: []const font.shape.Cell,
  72	) Allocator.Error!void {
  73	    const copy = try alloc.dupe(font.shape.Cell, cells);
  74	    const evicted = self.map.put(run.hash, copy);
  75	    if (evicted) |kv| {
  76	        alloc.free(kv.value);
  77	    }
  78	}
