  80	fn clear(self: *Cache, alloc: Allocator) void {
  81	    for (self.map.buckets, self.map.lengths) |b, l| {
  82	        for (b[0..l]) |kv| {
  83	            alloc.free(kv.value);
  84	        }
  85	    }
  86	    self.map.clear();
  87	}
