 82	    /// Resize the cell contents for the given grid size. This will
 83	    /// always invalidate the entire cell contents.
 84	    pub fn resize(
 85	        self: *Contents,
 86	        alloc: Allocator,
 87	        size: renderer.GridSize,
 88	    ) Allocator.Error!void {
 89	        const row_count: usize = size.rows;
 90	
 91	        // The two extra lists hold cursor cells: index 0 is drawn before the
 92	        // row contents, and index row_count + 1 is drawn after them.
 93	        const fg_rows = try alloc.alloc(CellTextRow, row_count + 2);
 94	        @memset(fg_rows, .empty);
 95	        errdefer {
 96	            for (fg_rows) |*row| row.deinit(alloc);
 97	            alloc.free(fg_rows);
 98	        }
 99	
100	        // Foreground rows hold glyphs plus underlines, overlines, and
101	        // strikethroughs. Three entries per column cover the common cases
102	        // without reserving space for every decoration combination. We can't
103	        // assume this capacity because combining glyphs and font substitutions
104	        // can produce arbitrarily many glyphs in one column.
105	        const fg_row_capacity = @as(usize, size.columns) * 3;
106	
107	        // The cursor lists need just one cell. The rest get the full capacity.
108	        fg_rows[0] = try .initCapacity(alloc, 1);
109	        fg_rows[row_count + 1] = try .initCapacity(alloc, 1);
110	        for (fg_rows[1 .. row_count + 1]) |*row| {
111	            row.* = try .initCapacity(alloc, fg_row_capacity);
112	        }
113	
114	        const bg_cells = try alloc.realloc(
115	            self.bg_cells,
116	            row_count * @as(usize, size.columns),
117	        );
118	
119	        // Perform the swap, no going back from here.
120	        errdefer comptime unreachable;
121	        for (self.fg_rows) |*row| row.deinit(alloc);
122	        alloc.free(self.fg_rows);
123	        self.size = size;
124	        self.bg_cells = bg_cells;
125	        self.fg_rows = fg_rows;
126	        self.reset();
127	    }
