  93	pub fn create(
  94	    alloc: Allocator,
  95	    comptime Userdata: type,
  96	    comptime callbackFn: *const fn (*macos.video.DisplayLink, ?*Userdata) void,
  97	    userdata: ?*Userdata,
  98	) !*DisplayLink {
  99	    const link = try macos.video.DisplayLink.createWithActiveCGDisplays();
 100	    errdefer link.release();
 101	    try link.setOutputCallback(Userdata, callbackFn, userdata);
 102	
 103	    const self = try alloc.create(DisplayLink);
 104	    errdefer alloc.destroy(self);
 105	    self.* = .{
 106	        .alloc = alloc,
 107	        .link = link,
 108	    };
