1748	
1749	        // This only covers the viewport, never overscan rows.
1750	        const row_slice = self.row_data.slice();
1751	        const vp_start = self.viewportStart();
1752	        const row_pins = row_slice.items(.pin)[vp_start..][0..self.rows];
1753	        const row_cells = row_slice.items(.cells)[vp_start..][0..self.rows];
1754	
1755	        // Our viewport point is sent in by the caller and can't be trusted.
1756	        // If it is outside the valid area then just return empty because
1757	        // we can't possibly have a link there.
1758	        if (viewport_point.x >= self.cols or
1759	            viewport_point.y >= self.rows) return result;
1760	
1761	        // Grab our link ID
1762	        const link_pin: PageList.Pin = row_pins[viewport_point.y];
1763	        const link_page: *page.Page = link_pin.node.page();
1764	        const link = link: {
1765	            const rac = link_page.getRowAndCell(
1766	                viewport_point.x,
1767	                link_pin.y,
1768	            );
1769	
1770	            // The likely scenario is that our mouse isn't even over a link.
1771	            if (!rac.cell.hyperlink) {
1772	                @branchHint(.likely);
1773	                return result;
1774	            }
1775	
1776	            const link_id = link_page.lookupHyperlink(rac.cell) orelse
1777	                return result;
1778	            break :link link_page.hyperlink_set.get(
1779	                link_page.memory,
1780	                link_id,
1781	            );
1782	        };
1783	
1784	        for (
1785	            0..,
1786	            row_pins,
1787	            row_cells,
1788	        ) |y, pin, cells| {
1789	            for (0.., cells.items(.raw)) |x, cell| {
1790	                if (!cell.hyperlink) continue;
1791	
1792	                const other_page: *page.Page = pin.node.page();
1793	                const other = link: {
1794	                    const rac = other_page.getRowAndCell(x, pin.y);
1795	                    const link_id = other_page.lookupHyperlink(rac.cell) orelse continue;
1796	                    break :link other_page.hyperlink_set.get(
1797	                        other_page.memory,
1798	                        link_id,
1799	                    );
1800	                };
1801	
1802	                if (link.eql(
1803	                    link_page.memory,
1804	                    other,
1805	                    other_page.memory,
1806	                )) try result.put(alloc, .{
1807	                    .y = @intCast(y),
1808	                    .x = @intCast(x),
1809	                }, {});
1810	            }
1811	        }
1812	
1813	        return result;
1814	    }
1815	};
 210	    pub fn blankPadding(self: ScreenSize, padding: Padding, grid: GridSize, cell: CellSize) Padding {
 211	        const grid_width = grid.columns * cell.width;
 212	        const grid_height = grid.rows * cell.height;
 213	        const padded_width = grid_width + (padding.left + padding.right);
 214	        const padded_height = grid_height + (padding.top + padding.bottom);
 215	
 216	        // Note these have to use a saturating subtraction to avoid underflow
 217	        // because our padding can cause the padded sizes to be larger than
 218	        // our real screen if the screen is shrunk to a minimal size such
 219	        // as 1x1.
 220	        const leftover_width = self.width -| padded_width;
 221	        const leftover_height = self.height -| padded_height;
 222	
 223	        return .{
 224	            .top = 0,
 225	            .bottom = leftover_height,
 226	            .right = leftover_width,
 227	            .left = 0,
 228	        };
 229	    }
