 197	/// Callback called by renderer.Thread when it begins. Called on the render
 198	/// thread. The EGL context was created at `init` time on the main thread;
  55	pub fn init(opts: Options) !Self {
  56	    const texture = try gl.Texture.create();
  57	    errdefer texture.destroy();
  58	    {
  59	        const bound_tex = try texture.bind(.@"2d");
  60	        defer bound_tex.unbind();
  61	        try bound_tex.parameter(.min_filter, .nearest);
  62	        try bound_tex.parameter(.mag_filter, .nearest);
  63	        try bound_tex.parameter(.wrap_s, .clamp_to_edge);
  64	        try bound_tex.parameter(.wrap_t, .clamp_to_edge);
  65	        try bound_tex.image2D(
  66	            0,
  67	            .srgba,
  68	            @intCast(opts.width),
  69	            @intCast(opts.height),
  70	            .rgba,
  71	            .unsigned_byte,
  72	            null,
  73	        );
  74	        try bound_tex.parameter(.base_level, 0);
  75	        try bound_tex.parameter(.max_level, 0);
  76	    }
  77	
  78	    const fbo = try gl.Framebuffer.create();
  79	    errdefer fbo.destroy();
  80	    {
  81	        const bound_fbo = try fbo.bind(.framebuffer);
  82	        defer bound_fbo.unbind();
  83	        try bound_fbo.texture2D(.color0, .@"2d", texture, 0);
  84	        switch (bound_fbo.checkStatus()) {
  85	            .complete => {},
  86	            else => |status| {
  87	                log.warn("render framebuffer incomplete status={}", .{status});
  88	                return error.FramebufferIncomplete;
  89	            },
  90	        }
  91	    }
  92	
  93	    // --- Export texture (plain RGBA8, for dma-buf export) ---
  94	    const export_texture = try gl.Texture.create();
  95	    errdefer export_texture.destroy();
  96	    {
  97	        const bound_tex = try export_texture.bind(.@"2d");
  98	        defer bound_tex.unbind();
  99	        try bound_tex.parameter(.min_filter, .nearest);
 100	        try bound_tex.parameter(.mag_filter, .nearest);
 101	        try bound_tex.parameter(.wrap_s, .clamp_to_edge);
 102	        try bound_tex.parameter(.wrap_t, .clamp_to_edge);
 103	        try bound_tex.image2D(
 104	            0,
 105	            .rgba,
 106	            @intCast(opts.width),
 107	            @intCast(opts.height),
 108	            .rgba,
 109	            .unsigned_byte,
 110	            null,
 111	        );
 112	        try bound_tex.parameter(.base_level, 0);
 113	        try bound_tex.parameter(.max_level, 0);
 114	    }
 115	
 116	    const export_fbo = try gl.Framebuffer.create();
 117	    errdefer export_fbo.destroy();
 118	    {
 119	        const bound_fbo = try export_fbo.bind(.framebuffer);
 120	        defer bound_fbo.unbind();
 121	        try bound_fbo.texture2D(.color0, .@"2d", export_texture, 0);
 122	        switch (bound_fbo.checkStatus()) {
 123	            .complete => {},
 124	            else => |status| {
 125	                log.warn("export framebuffer incomplete status={}", .{status});
 126	                return error.FramebufferIncomplete;
 127	            },
 128	        }
 129	    }
 130	
 131	    return .{
 132	        .framebuffer = fbo,
 133	        .texture = texture,
 134	        .export_framebuffer = export_fbo,
 135	        .export_texture = export_texture,
 136	        .width = opts.width,
 137	        .height = opts.height,
 138	    };
 139	}
