2238	            std.ArrayList(RenderState.ImagePlacement),
2239	            &state.kitty.placed,
2240	            &state.kitty.placed_prev,
2241	        );
2242	        state.kitty.placed.clearRetainingCapacity();
2243	        if (state.kitty.roots.items.len == 0) return;
2244	
2245	        const range = state.rowDataRange();
2246	        const captured_len: isize = @intCast(range.end - range.start);
2247	        const captured_placeholders = state.row_data.items(.placeholders)[range.start..range.end];
2248	        const viewport_y_base = state.viewportY(range.start);
2249	
2250	        // Group the captured rows by page, for `rowIndexOfPin`. Only
2251	        // `pin` anchors need this.
2252	        state.kitty.chunks.clearRetainingCapacity();
2253	        if (state.kitty.virtual_anchors < state.kitty.roots.items.len) {
2254	            const captured_pins = state.row_data.items(.pin)[range.start..range.end];
2255	            try state.kitty.chunks.ensureTotalCapacity(alloc, captured_pins.len);
2256	            for (captured_pins, 0..) |pin, i| {
2257	                if (i > 0 and captured_pins[i - 1].node == pin.node) continue;
2258	                state.kitty.chunks.appendAssumeCapacity(.{
2259	                    .node = pin.node,
2260	                    .start = pin.y,
2261	                    .index = @intCast(i),
2262	                });
2263	            }
2264	        }
2265	
2266	        for (state.kitty.roots.items) |root| {
2267	            const p = root.placement;
2268	
2269	            // Where the anchor is. `y` counts captured rows, where 0 is
2270	            // the first captured row.
2271	            const origin: struct { x: i64, y: i64 } = switch (root.anchor) {
2272	                // The top-left corner of the virtual placement's cells:
2273	                // the smallest column and the smallest row of those
2274	                // cells. Without any of those cells in the captured rows,
2275	                // the placement isn't drawn, which matches Kitty. There
2276	                // are rarely more than a few of these, so a simple scan of
2277	                // the runs for each one is fine.
2278	                .virtual => |key| origin: {
2279	                    var origin: ?struct { x: i64, y: i64 } = null;
2280	                    for (captured_placeholders, 0..) |runs, y| {
2281	                        for (runs.items) |run| {
2282	                            const target = run.target orelse continue;
2283	                            if (!target.eql(key)) continue;
