2300	                        state.kitty.chunks.items,
2301	                        pin.*,
2302	                        captured_len,
2303	                        p.rows,
2304	                        root.vertical_offset,
2305	                    ) orelse continue;
2306	                    break :origin .{ .x = pin.x, .y = y };
2307	                },
2308	            };
