     5	layout(origin_upper_left) in vec4 gl_FragCoord;
     6	
     7	layout(binding = 0) uniform sampler2D image;
     8	
     9	flat in vec4 bg_color;
    10	flat in vec2 offset;
    11	flat in vec2 scale;
    12	flat in float opacity;
    13	flat in uint repeat;
    14	
    15	layout(location = 0) out vec4 out_FragColor;
    16	
    17	void main() {
    18	    bool use_linear_blending = (bools & USE_LINEAR_BLENDING) != 0;
    19	
    20	    // Our texture coordinate is based on the screen position, offset by the
    21	    // dest rect origin, and scaled by the ratio between the dest rect size
    22	    // and the original texture size, which effectively scales the original
    23	    // size of the texture to the dest rect size.
    24	    vec2 tex_coord = (gl_FragCoord.xy - offset) * scale;
    25	
    26	    vec2 tex_size = textureSize(image, 0);
    27	
    28	    // If we need to repeat the texture, wrap the coordinates.
    29	    if (repeat != 0) {
    30	        tex_coord = mod(mod(tex_coord, tex_size) + tex_size, tex_size);
    31	    }
    32	
    33	    vec4 rgba;
    34	    // If we're out of bounds, we have no color,
    35	    // otherwise we sample the texture for it.
    36	    if (any(lessThan(tex_coord, vec2(0.0))) ||
    37	            any(greaterThan(tex_coord, tex_size)))
    38	    {
    39	        rgba = vec4(0.0);
    40	    } else {
    41	        // We divide by the texture size to normalize for sampling.
    42	        rgba = texture(image, tex_coord / tex_size);
    43	
    44	        if (!use_linear_blending) {
    45	            rgba = unlinearize(rgba);
    46	        }
    47	
    48	        rgba.rgb *= rgba.a;
    49	    }
    50	
    51	    // Multiply it by the configured opacity, but cap it at
    52	    // the value that will make it fully opaque relative to
    53	    // the background color alpha, so it isn't overexposed.
    54	    rgba *= min(opacity, 1.0 / bg_color.a);
    55	
    56	    // Blend it on to a fully opaque version of the background color.
    57	    rgba += max(vec4(0.0), vec4(bg_color.rgb, 1.0) * vec4(1.0 - rgba.a));
    58	
    59	    // Multiply everything by the background color alpha.
    60	    rgba *= bg_color.a;
    61	
    62	    out_FragColor = rgba;
    63	}

