   801	    /// Start the one-shot timer, or move its deadline if it is already active.
   802	    fn schedule(self: *Compression, thread: *Thread, delay_ms: u64) void {
   803	        self.timer.reset(
   804	            &thread.loop,
   805	            &self.completion,
   806	            &self.reset_completion,
   807	            delay_ms,
   808	            Thread,
   809	            thread,
   810	            timerCallback,
   811	        );
