2231	    /// never reads the image storage, so it is cheap enough to run on
2232	    /// every scroll. The old contents of `placed` move to `placed_prev`.
2233	    fn placeRoots(
2234	        state: *RenderState,
2235	        alloc: Allocator,
2236	    ) Allocator.Error!void {
2237	        std.mem.swap(
2238	            std.ArrayList(RenderState.ImagePlacement),
2239	            &state.kitty.placed,
2240	            &state.kitty.placed_prev,
2241	        );
2242	        state.kitty.placed.clearRetainingCapacity();
2243	        if (state.kitty.roots.items.len == 0) return;
