2245	        const range = state.rowDataRange();
2246	        const captured_len: isize = @intCast(range.end - range.start);
2247	        const captured_placeholders = state.row_data.items(.placeholders)[range.start..range.end];
2248	        const viewport_y_base = state.viewportY(range.start);
