2254	            const captured_pins = state.row_data.items(.pin)[range.start..range.end];
2255	            try state.kitty.chunks.ensureTotalCapacity(alloc, captured_pins.len);
2256	            for (captured_pins, 0..) |pin, i| {
2257	                if (i > 0 and captured_pins[i - 1].node == pin.node) continue;
2258	                state.kitty.chunks.appendAssumeCapacity(.{
2259	                    .node = pin.node,
2260	                    .start = pin.y,
2261	                    .index = @intCast(i),
2262	                });
