2275	                // the placement isn't drawn, which matches Kitty. There
2276	                // are rarely more than a few of these, so a simple scan of
2277	                // the runs for each one is fine.
2278	                .virtual => |key| origin: {
2279	                    var origin: ?struct { x: i64, y: i64 } = null;
