2331	    /// `rows` tall. If that placement can't reach the captured rows, the
2332	    /// search may stop early and return null.
2333	    ///
2334	    /// For example, with 5 captured rows and a placement 3 rows tall:
2335	    ///
2336	    ///   - A pin 2 rows above the first captured row returns -2. The
2337	    ///     placement covers rows -2 to 0, so its last row is visible.
2338	    ///   - A pin 10 rows above it may return null, because the placement
2339	    ///     ends at row -8.
2340	    ///
2341	    /// Pins on captured pages are found with the chunk table alone. Other
2342	    /// pins are found by walking the pages above or below. This is much
2343	    /// cheaper than `pointFromPin`, which counts rows from the top of the
2344	    /// scrollback. It reads page list nodes, so it is only safe while
2345	    /// the terminal can't change, such as during `beginUpdate`.
2401	    fn rebuildRoots(
2402	        state: *RenderState,
2403	        alloc: Allocator,
2404	        t: *const Terminal,
2405	    ) Allocator.Error!void {
2406	        const storage = &t.screens.active.kitty_images;
2407	        state.kitty.roots.clearRetainingCapacity();
2408	        state.kitty.virtual_anchors = 0;
2409	        var it = storage.placements.iterator();
2410	        while (it.next()) |kv| {
2411	            // Keep placements with garbage pins. A pin can become
2412	            // garbage without a generation change, so `placeRoots`
2413	            // checks for it every time instead.
2414	            const root: Root = switch (kv.value_ptr.location) {
2415	                .pin => |pin| .{
2416	                    .anchor = .{ .pin = pin },
2417	                    .horizontal_offset = 0,
2418	                    .vertical_offset = 0,
2419	                    .placement = template(
2420	                        storage,
2421	                        t,
2422	                        kv.key_ptr.*,
2423	                        kv.value_ptr,
2424	                        .fixed,
2425	                    ) orelse continue,
2426	                },
2427	
2428	                .virtual => continue,
2429	
2430	                .relative => |rel| root: {
2431	                    // Follow the chain of parents to the placement at its
2432	                    // start. A broken chain is never drawn.
2433	                    const chain = storage.resolveChain(rel) orelse continue;
2434	                    break :root .{
2435	                        .anchor = switch (chain.root.location) {
2436	                            .virtual => .{ .virtual = chain.root_key },
2437	                            .pin => |pin| .{ .pin = pin },
2438	
2439	                            // resolveChain roots are never relative.
2440	                            .relative => unreachable,
2441	                        },
2442	                        .horizontal_offset = chain.horizontal_offset,
2443	                        .vertical_offset = chain.vertical_offset,
2444	                        .placement = template(
2445	                            storage,
2446	                            t,
2447	                            kv.key_ptr.*,
2448	                            kv.value_ptr,
2449	                            .relative,
2450	                        ) orelse continue,
2451	                    };
2452	                },
2453	            };
