--- src/renderer/shaders/glsl/cell_bg.f.glsl
     1	#include "common.glsl"
     2	
     3	// Position the origin to the upper left
     4	layout(origin_upper_left) in vec4 gl_FragCoord;
     5	
     6	// Must declare this output for some versions of OpenGL.
     7	layout(location = 0) out vec4 out_FragColor;
     8	
     9	layout(binding = 1, std430) readonly buffer bg_cells {
    10	    uint cells[];
    11	};
    12	
    13	vec4 cell_bg() {
    14	    uvec2 grid_size = unpack2u16(grid_size_packed_2u16);
    15	    ivec2 grid_pos = ivec2(floor((gl_FragCoord.xy - grid_padding.wx) / cell_size));
    16	    bool use_linear_blending = (bools & USE_LINEAR_BLENDING) != 0;
    17	
    18	    vec4 bg = vec4(0.0);
    19	
    20	    // Clamp x position, extends edge bg colors in to padding on sides.
    21	    if (grid_pos.x < 0) {
    22	        if ((padding_extend & EXTEND_LEFT) != 0) {
    23	            grid_pos.x = 0;
    24	        } else {
    25	            return bg;
    26	        }
    27	    } else if (grid_pos.x > grid_size.x - 1) {
    28	        if ((padding_extend & EXTEND_RIGHT) != 0) {
    29	            grid_pos.x = int(grid_size.x) - 1;
    30	        } else {
    31	            return bg;
    32	        }
    33	    }
    34	
    35	    // Clamp y position if we should extend, otherwise discard if out of bounds.
    36	    if (grid_pos.y < 0) {
    37	        if ((padding_extend & EXTEND_UP) != 0) {
    38	            grid_pos.y = 0;
    39	        } else {
    40	            return bg;
    41	        }
    42	    } else if (grid_pos.y > grid_size.y - 1) {
    43	        if ((padding_extend & EXTEND_DOWN) != 0) {
    44	            grid_pos.y = int(grid_size.y) - 1;
    45	        } else {
    46	            return bg;
    47	        }
    48	    }
    49	
    50	    // Load the color for the cell.
    51	    vec4 cell_color = load_color(
    52	            unpack4u8(cells[grid_pos.y * grid_size.x + grid_pos.x]),
    53	            use_linear_blending
    54	        );
    55	
    56	    return cell_color;
    57	}
    58	
    59	void main() {
    60	    out_FragColor = cell_bg();
    61	}

--- src/renderer/shaders/glsl/cell_text.v.glsl
     1	#include "common.glsl"
     2	
     3	// The position of the glyph in the texture (x, y)
     4	layout(location = 0) in uvec2 glyph_pos;
     5	
     6	// The size of the glyph in the texture (w, h)
     7	layout(location = 1) in uvec2 glyph_size;
     8	
     9	// The left and top bearings for the glyph (x, y)
    10	layout(location = 2) in ivec2 bearings;
    11	
    12	// The grid coordinates (x, y) where x < columns and y < rows
    13	layout(location = 3) in uvec2 grid_pos;
    14	
    15	// The color of the rendered text glyph.
    16	layout(location = 4) in uvec4 color;
    17	
    18	// Which atlas this glyph is in.
    19	layout(location = 5) in uint atlas;
    20	
    21	// Misc glyph properties.
    22	layout(location = 6) in uint glyph_bools;
    23	
    24	// Values `atlas` can take.
    25	const uint ATLAS_GRAYSCALE = 0u;
    26	const uint ATLAS_COLOR = 1u;
    27	
    28	// Masks for the `glyph_bools` attribute
    29	const uint NO_MIN_CONTRAST = 1u;
    30	const uint IS_CURSOR_GLYPH = 2u;
    31	
    32	out CellTextVertexOut {
    33	    flat uint atlas;
    34	    flat vec4 color;
    35	    flat vec4 bg_color;
    36	    vec2 tex_coord;
    37	} out_data;
    38	
    39	layout(binding = 1, std430) readonly buffer bg_cells {
    40	    uint bg_colors[];
    41	};
    42	
    43	void main() {
    44	    uvec2 grid_size = unpack2u16(grid_size_packed_2u16);
    45	    uvec2 cursor_pos = unpack2u16(cursor_pos_packed_2u16);
    46	    bool cursor_wide = (bools & CURSOR_WIDE) != 0;
    47	    bool use_linear_blending = (bools & USE_LINEAR_BLENDING) != 0;
    48	
    49	    // Convert the grid x, y into world space x, y by accounting for cell size
    50	    vec2 cell_pos = cell_size * vec2(grid_pos);
    51	
    52	    int vid = gl_VertexID;
    53	
    54	    // We use a triangle strip with 4 vertices to render quads,
    55	    // so we determine which corner of the cell this vertex is in
    56	    // based on the vertex ID.
    57	    //
    58	    //   0 --> 1
    59	    //   |   .'|
    60	    //   |  /  |
    61	    //   | L   |
    62	    //   2 --> 3
    63	    //
    64	    // 0 = top-left  (0, 0)
    65	    // 1 = top-right (1, 0)
    66	    // 2 = bot-left  (0, 1)
    67	    // 3 = bot-right (1, 1)
    68	    vec2 corner;
    69	    corner.x = float(vid == 1 || vid == 3);
    70	    corner.y = float(vid == 2 || vid == 3);
    71	
    72	    out_data.atlas = atlas;
    73	
    74	    //              === Grid Cell ===
    75	    //      +X
    76	    // 0,0--...->
    77	    //   |
    78	    //   . offset.x = bearings.x
    79	    // +Y.               .|.
    80	    //   .               | |
    81	    //   |   cell_pos -> +-------+   _.
    82	    //   v             ._|       |_. _|- offset.y = cell_size.y - bearings.y
    83	    //                 | | .###. | |
    84	    //                 | | #...# | |
    85	    //   glyph_size.y -+ | ##### | |
    86	    //                 | | #.... | +- bearings.y
    87	    //                 |_| .#### | |
    88	    //                   |       |_|
    89	    //                   +-------+
    90	    //                     |_._|
    91	    //                       |
    92	    //                  glyph_size.x
    93	    //
    94	    // In order to get the top left of the glyph, we compute an offset based on
    95	    // the bearings. The Y bearing is the distance from the bottom of the cell
    96	    // to the top of the glyph, so we subtract it from the cell height to get
    97	    // the y offset. The X bearing is the distance from the left of the cell
    98	    // to the left of the glyph, so it works as the x offset directly.
    99	
   100	    vec2 size = vec2(glyph_size);
   101	    vec2 offset = vec2(bearings);
   102	
   103	    offset.y = cell_size.y - offset.y;
   104	
   105	    // Calculate the final position of the cell which uses our glyph size
   106	    // and glyph offset to create the correct bounding box for the glyph.
   107	    cell_pos = cell_pos + size * corner + offset;
   108	    gl_Position = projection_matrix * vec4(cell_pos.x, cell_pos.y, 0.0f, 1.0f);
   109	
   110	    // Calculate the texture coordinate in pixels. This is NOT normalized
   111	    // (between 0.0 and 1.0), and does not need to be, since the texture will
   112	    // be sampled with pixel coordinate mode.
   113	    out_data.tex_coord = vec2(glyph_pos) + vec2(glyph_size) * corner;
   114	
   115	    // Get our color. We always fetch a linearized version to
   116	    // make it easier to handle minimum contrast calculations.
   117	    out_data.color = load_color(color, true);
   118	    // Get the BG color
   119	    out_data.bg_color = load_color(
   120	            unpack4u8(bg_colors[grid_pos.y * grid_size.x + grid_pos.x]),
   121	            true
   122	        );
   123	    // Blend it with the global bg color
   124	    vec4 global_bg = load_color(
   125	            unpack4u8(bg_color_packed_4u8),
   126	            true
   127	        );
   128	    out_data.bg_color += global_bg * vec4(1.0 - out_data.bg_color.a);
   129	
   130	    // If we have a minimum contrast, we need to check if we need to
   131	    // change the color of the text to ensure it has enough contrast
   132	    // with the background.
   133	    if (min_contrast > 1.0f && (glyph_bools & NO_MIN_CONTRAST) == 0) {
   134	        // Ensure our minimum contrast
   135	        out_data.color = contrasted_color(min_contrast, out_data.color, out_data.bg_color);
   136	    }
   137	
   138	    // Check if current position is under cursor (including wide cursor)
   139	    bool is_cursor_pos = ((grid_pos.x == cursor_pos.x) || (cursor_wide && (grid_pos.x == (cursor_pos.x + 1)))) && (grid_pos.y == cursor_pos.y);
   140	
   141	    // If this cell is the cursor cell, but we're not processing
   142	    // the cursor glyph itself, then we need to change the color.
   143	    if ((glyph_bools & IS_CURSOR_GLYPH) == 0 && is_cursor_pos) {
   144	        out_data.color = load_color(unpack4u8(cursor_color_packed_4u8), use_linear_blending);
   145	    }
   146	}

--- src/renderer/shaders/glsl/cell_text.f.glsl
     1	#include "common.glsl"
     2	
     3	layout(binding = 0) uniform sampler2DRect atlas_grayscale;
     4	layout(binding = 1) uniform sampler2DRect atlas_color;
     5	
     6	in CellTextVertexOut {
     7	    flat uint atlas;
     8	    flat vec4 color;
     9	    flat vec4 bg_color;
    10	    vec2 tex_coord;
    11	} in_data;
    12	
    13	// Values `atlas` can take.
    14	const uint ATLAS_GRAYSCALE = 0u;
    15	const uint ATLAS_COLOR = 1u;
    16	
    17	// Must declare this output for some versions of OpenGL.
    18	layout(location = 0) out vec4 out_FragColor;
    19	
    20	void main() {
    21	    bool use_linear_blending = (bools & USE_LINEAR_BLENDING) != 0;
    22	    bool use_linear_correction = (bools & USE_LINEAR_CORRECTION) != 0;
    23	
    24	    switch (in_data.atlas) {
    25	        default:
    26	        case ATLAS_GRAYSCALE:
    27	        {
    28	            // Our input color is always linear.
    29	            vec4 color = in_data.color;
    30	
    31	            // If we're not doing linear blending, then we need to
    32	            // re-apply the gamma encoding to our color manually.
    33	            //
    34	            // Since the alpha is premultiplied, we need to divide
    35	            // it out before unlinearizing and re-multiply it after.
    36	            if (!use_linear_blending) {
    37	                color.rgb /= vec3(color.a);
    38	                color = unlinearize(color);
    39	                color.rgb *= vec3(color.a);
    40	            }
    41	
    42	            // Fetch our alpha mask for this pixel.
    43	            float a = texture(atlas_grayscale, in_data.tex_coord).r;
    44	
    45	            // Linear blending weight correction corrects the alpha value to
    46	            // produce blending results which match gamma-incorrect blending.
    47	            if (use_linear_correction) {
    48	                // Short explanation of how this works:
    49	                //
    50	                // We get the luminances of the foreground and background colors,
    51	                // and then unlinearize them and perform blending on them. This
    52	                // gives us our desired luminance, which we derive our new alpha
    53	                // value from by mapping the range [bg_l, fg_l] to [0, 1], since
    54	                // our final blend will be a linear interpolation from bg to fg.
    55	                //
    56	                // This yields virtually identical results for grayscale blending,
    57	                // and very similar but non-identical results for color blending.
    58	                vec4 bg = in_data.bg_color;
    59	                float fg_l = luminance(color.rgb);
    60	                float bg_l = luminance(bg.rgb);
    61	                // To avoid numbers going haywire, we don't apply correction
    62	                // when the bg and fg luminances are within 0.001 of each other.
    63	                if (abs(fg_l - bg_l) > 0.001) {
    64	                    float blend_l = linearize(unlinearize(fg_l) * a + unlinearize(bg_l) * (1.0 - a));
    65	                    a = clamp((blend_l - bg_l) / (fg_l - bg_l), 0.0, 1.0);
    66	                }
    67	            }
    68	
    69	            // Multiply our whole color by the alpha mask.
    70	            // Since we use premultiplied alpha, this is
    71	            // the correct way to apply the mask.
    72	            color *= a;
    73	
    74	            out_FragColor = color;
    75	            return;
    76	        }
    77	
    78	        case ATLAS_COLOR:
    79	        {
    80	            // For now, we assume that color glyphs
    81	            // are already premultiplied linear colors.
    82	            vec4 color = texture(atlas_color, in_data.tex_coord);
    83	
    84	            // If we are doing linear blending, we can return this right away.
    85	            if (use_linear_blending) {
    86	                out_FragColor = color;
    87	                return;
    88	            }
    89	
    90	            // Otherwise we need to unlinearize the color. Since the alpha is
    91	            // premultiplied, we need to divide it out before unlinearizing.
    92	            color.rgb /= vec3(color.a);
    93	            color = unlinearize(color);
    94	            color.rgb *= vec3(color.a);
    95	
    96	            out_FragColor = color;
    97	            return;
    98	        }
    99	    }
   100	}

--- src/renderer/shaders/glsl/image.v.glsl
     1	#include "common.glsl"
     2	
     3	layout(binding = 0) uniform sampler2D image;
     4	
     5	layout(location = 0) in vec2 grid_pos;
     6	layout(location = 1) in vec2 cell_offset;
     7	layout(location = 2) in vec4 source_rect;
     8	layout(location = 3) in vec2 dest_size;
     9	
    10	out vec2 tex_coord;
    11	
    12	void main() {
    13	    int vid = gl_VertexID;
    14	
    15	    // We use a triangle strip with 4 vertices to render quads,
    16	    // so we determine which corner of the cell this vertex is in
    17	    // based on the vertex ID.
    18	    //
    19	    //   0 --> 1
    20	    //   |   .'|
    21	    //   |  /  |
    22	    //   | L   |
    23	    //   2 --> 3
    24	    //
    25	    // 0 = top-left  (0, 0)
    26	    // 1 = top-right (1, 0)
    27	    // 2 = bot-left  (0, 1)
    28	    // 3 = bot-right (1, 1)
    29	    vec2 corner;
    30	    corner.x = float(vid == 1 || vid == 3);
    31	    corner.y = float(vid == 2 || vid == 3);
    32	
    33	    // The texture coordinates start at our source x/y
    34	    // and add the width/height depending on the corner.
    35	    tex_coord = source_rect.xy;
    36	    tex_coord += source_rect.zw * corner;
    37	
    38	    // Normalize the coordinates.
    39	    tex_coord /= textureSize(image, 0);
    40	
    41	    // The position of our image starts at the top-left of the grid cell and
    42	    // adds the source rect width/height components.
    43	    vec2 image_pos = (cell_size * grid_pos) + cell_offset;
    44	    image_pos += dest_size * corner;
    45	
    46	    gl_Position = projection_matrix * vec4(image_pos.xy, 1.0, 1.0);
    47	}

--- src/renderer/shaders/glsl/bg_image.v.glsl
     1	#include "common.glsl"
     2	
     3	layout(binding = 0) uniform sampler2D image;
     4	
     5	layout(location = 0) in float in_opacity;
     6	layout(location = 1) in uint info;
     7	
     8	// 4 bits of info.
     9	const uint BG_IMAGE_POSITION = 15u;
    10	const uint BG_IMAGE_TL = 0u;
    11	const uint BG_IMAGE_TC = 1u;
    12	const uint BG_IMAGE_TR = 2u;
    13	const uint BG_IMAGE_ML = 3u;
    14	const uint BG_IMAGE_MC = 4u;
    15	const uint BG_IMAGE_MR = 5u;
    16	const uint BG_IMAGE_BL = 6u;
    17	const uint BG_IMAGE_BC = 7u;
    18	const uint BG_IMAGE_BR = 8u;
    19	
    20	// 2 bits of info shifted 4.
    21	const uint BG_IMAGE_FIT = 3u << 4;
    22	const uint BG_IMAGE_CONTAIN = 0u << 4;
    23	const uint BG_IMAGE_COVER = 1u << 4;
    24	const uint BG_IMAGE_STRETCH = 2u << 4;
    25	const uint BG_IMAGE_NO_FIT = 3u << 4;
    26	
    27	// 1 bit of info shifted 6.
    28	const uint BG_IMAGE_REPEAT = 1u << 6;
    29	
    30	flat out vec4 bg_color;
    31	flat out vec2 offset;
    32	flat out vec2 scale;
    33	flat out float opacity;
    34	// We use a uint to pass the repeat value because
    35	// bools aren't allowed for vertex outputs in OpenGL.
    36	flat out uint repeat;
    37	
    38	void main() {
    39	    bool use_linear_blending = (bools & USE_LINEAR_BLENDING) != 0;
    40	
    41	    vec4 position;
    42	    position.x = (gl_VertexID == 2) ? 3.0 : -1.0;
    43	    position.y = (gl_VertexID == 0) ? -3.0 : 1.0;
    44	    position.z = 1.0;
    45	    position.w = 1.0;
    46	
    47	    // Single triangle is clipped to viewport.
    48	    //
    49	    // X <- vid == 0: (-1, -3)
    50	    // |\
    51	    // | \
    52	    // |  \
    53	    // |###\
    54	    // |#+# \ `+` is (0, 0). `#`s are viewport area.
    55	    // |###  \
    56	    // X------X <- vid == 2: (3, 1)
    57	    // ^
    58	    // vid == 1: (-1, 1)
    59	
    60	    gl_Position = position;
    61	
    62	    opacity = in_opacity;
    63	
    64	    repeat = info & BG_IMAGE_REPEAT;
    65	
    66	    vec2 screen_size = screen_size;
    67	    vec2 tex_size = textureSize(image, 0);
    68	
    69	    vec2 dest_size = tex_size;
    70	    switch (info & BG_IMAGE_FIT) {
    71	        // For `contain` we scale by a factor that makes the image
    72	        // width match the screen width or makes the image height
    73	        // match the screen height, whichever is smaller.
    74	        case BG_IMAGE_CONTAIN: {
    75	            float scale = min(screen_size.x / tex_size.x, screen_size.y / tex_size.y);
    76	            dest_size = tex_size * scale;
    77	        } break;
    78	
    79	        // For `cover` we scale by a factor that makes the image
    80	        // width match the screen width or makes the image height
    81	        // match the screen height, whichever is larger.
    82	        case BG_IMAGE_COVER: {
    83	            float scale = max(screen_size.x / tex_size.x, screen_size.y / tex_size.y);
    84	            dest_size = tex_size * scale;
    85	        } break;
    86	
    87	        // For `stretch` we stretch the image to the size of
    88	        // the screen without worrying about aspect ratio.
    89	        case BG_IMAGE_STRETCH: {
    90	            dest_size = screen_size;
    91	        } break;
    92	
    93	        // For `none` we just use the original texture size.
    94	        case BG_IMAGE_NO_FIT: {
    95	            dest_size = tex_size;
    96	        } break;
    97	    }
    98	
    99	    vec2 start = vec2(0.0);
   100	    vec2 mid = (screen_size - dest_size) / vec2(2.0);
   101	    vec2 end = screen_size - dest_size;
   102	
   103	    vec2 dest_offset = mid;
   104	    switch (info & BG_IMAGE_POSITION) {
   105	        case BG_IMAGE_TL: {
   106	            dest_offset = vec2(start.x, start.y);
   107	        } break;
   108	        case BG_IMAGE_TC: {
   109	            dest_offset = vec2(mid.x, start.y);
   110	        } break;
   111	        case BG_IMAGE_TR: {
   112	            dest_offset = vec2(end.x, start.y);
   113	        } break;
   114	        case BG_IMAGE_ML: {
   115	            dest_offset = vec2(start.x, mid.y);
   116	        } break;
   117	        case BG_IMAGE_MC: {
   118	            dest_offset = vec2(mid.x, mid.y);
   119	        } break;
   120	        case BG_IMAGE_MR: {
   121	            dest_offset = vec2(end.x, mid.y);
   122	        } break;
   123	        case BG_IMAGE_BL: {
   124	            dest_offset = vec2(start.x, end.y);
   125	        } break;
   126	        case BG_IMAGE_BC: {
   127	            dest_offset = vec2(mid.x, end.y);
   128	        } break;
   129	        case BG_IMAGE_BR: {
   130	            dest_offset = vec2(end.x, end.y);
   131	        } break;
   132	    }
   133	
   134	    offset = dest_offset;
   135	    scale = tex_size / dest_size;
