  71	    /// Fills matches with the matches from regex link matches.
  72	    pub fn renderCellMap(
  73	        self: *const Set,
  74	        alloc: Allocator,
  75	        result: *terminal.RenderState.CellSet,
  76	        render_state: *const terminal.RenderState,
  77	        mouse_viewport: ?point.Coordinate,
  78	        mouse_mods: inputpkg.Mods,
  79	    ) !void {
  80	        // Fast path, not very likely since we have default links.
  81	        if (self.links.len == 0) return;
  82	
  83	        // Determine if any links are active before building the string and
  84	        // byte-to-cell map. Those buffers scale with viewport size and this
  85	        // function runs during frame updates, so avoid allocating them when
  86	        // the current mouse/modifier state can't highlight any regex links.
  87	        for (self.links) |*link| {
  88	            if (link.active(mouse_viewport, mouse_mods)) break;
  89	        } else return;
  90	
  91	        // Convert our render state to a string + byte map.
  92	        var builder: std.Io.Writer.Allocating = .init(alloc);
  93	        defer builder.deinit();
  94	        var map: terminal.RenderState.StringMap = .empty;
  95	        defer map.deinit(alloc);
  96	        try render_state.string(&builder.writer, .{
  97	            .alloc = alloc,
  98	            .map = &map,
  99	        });
 100	
 101	        const str = builder.writer.buffered();
 102	
 103	        // Go through each link and see if we have any matches.
 104	        for (self.links) |*link| {
 105	            if (!link.active(mouse_viewport, mouse_mods)) continue;
 106	
 107	            var offset: usize = 0;
 108	            while (offset < str.len) {
 109	                var region = link.regex.search(
 110	                    str[offset..],
 111	                    .{},
 112	                ) catch |err| switch (err) {
 113	                    error.Mismatch => break,
 114	                    else => return err,
 115	                };
 116	                defer region.deinit();
 117	
 118	                // We have a match!
 119	                const offset_start: usize = @intCast(region.starts()[0]);
 120	                const offset_end: usize = @intCast(region.ends()[0]);
 121	                const start = offset + offset_start;
 122	                const end = offset + offset_end;
 123	
 124	                // Increment our offset by the number of bytes in the match.
 125	                // We defer this so that we can return the match before
 126	                // modifying the offset.
 127	                defer offset = end;
 128	
 129	                switch (link.highlight) {
 130	                    .always, .always_mods => {},
 131	                    .hover, .hover_mods => if (mouse_viewport) |vp| {
 132	                        for (map.items[start..end]) |pt| {
 133	                            if (pt.eql(vp)) break;
 134	                        } else continue;
 135	                    } else continue,
 136	                }
