  83	        // Determine if any links are active before building the string and
  84	        // byte-to-cell map. Those buffers scale with viewport size and this
  85	        // function runs during frame updates, so avoid allocating them when
  86	        // the current mouse/modifier state can't highlight any regex links.
  87	        for (self.links) |*link| {
  88	            if (link.active(mouse_viewport, mouse_mods)) break;
  89	        } else return;
