  91	        // Convert our render state to a string + byte map.
  92	        var builder: std.Io.Writer.Allocating = .init(alloc);
  93	        defer builder.deinit();
  94	        var map: terminal.RenderState.StringMap = .empty;
  95	        defer map.deinit(alloc);
  96	        try render_state.string(&builder.writer, .{
  97	            .alloc = alloc,
  98	            .map = &map,
  99	        });
 100	
 101	        const str = builder.writer.buffered();
 102	
 103	        // Go through each link and see if we have any matches.
 104	        for (self.links) |*link| {
 105	            if (!link.active(mouse_viewport, mouse_mods)) continue;
 106	
 107	            var offset: usize = 0;
 108	            while (offset < str.len) {
 109	                var region = link.regex.search(
 110	                    str[offset..],
 111	                    .{},
 112	                ) catch |err| switch (err) {
 113	                    error.Mismatch => break,
