2347	        chunks: []const Chunk,
2348	        pin: PageList.Pin,
2349	        captured_len: isize,
2350	        rows: u32,
2351	        vertical_offset: i32,
2352	    ) ?isize {
2353	        if (chunks.len == 0) return null;
2354	
2355	        // A pin on a page with captured rows. This also covers pins on
2356	        // rows of those pages that aren't captured.
2357	        for (chunks) |chunk| {
2358	            if (chunk.node != pin.node) continue;
2359	            return chunk.index + @as(isize, pin.y) - @as(isize, chunk.start);
2360	        }
2361	
2362	        // A pin on a page above the captured rows. The placement's last
2363	        // row is the pin's row plus `reach`, so it is only visible when
2364	        // the pin's row is -reach or more. Walk up a page at a time, and
2365	        // stop once a page's last row is too far up. `bottom` is the
2366	        // last row of the page being checked.
2367	        const reach: isize = @as(isize, @intCast(rows)) - 1 + @max(0, vertical_offset);
2368	        const first = chunks[0];
2369	        var bottom: isize = first.index - @as(isize, first.start) - 1;
2370	        var node = first.node.prev;
2371	        while (node) |n| : (node = n.prev) {
2372	            if (bottom < -reach) break;
2373	            const top = bottom - (@as(isize, n.rows()) - 1);
2374	            if (n == pin.node) return top + pin.y;
2375	            bottom = top - 1;
2376	        }
2377	
2378	        // A pin on a page below the captured rows. Only a negative
2379	        // offset can move such a placement up into them. Its first row
2380	        // is the pin's row plus the offset, which must be less than
2381	        // `captured_len`. Walk down a page at a time, and stop once a
2382	        // page's first row is too far down. `top` is the first row of
2383	        // the page being checked.
2384	        if (vertical_offset >= 0) return null;
2385	        const last = chunks[chunks.len - 1];
2386	        var top: isize = last.index - @as(isize, last.start) + last.node.rows();
2387	        node = last.node.next;
2388	        while (node) |n| : (node = n.next) {
2389	            if (top + vertical_offset >= captured_len) break;
2390	            if (n == pin.node) return top + pin.y;
2391	            top += n.rows();
2392	        }
